package api

import (
	"bytes"
	"encoding/json"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"testing"

	"lanora/services/api/internal/store"
)

func testAPI(t *testing.T) http.Handler { t.Helper(); db,e:=store.Open(":memory:");if e!=nil{t.Fatal(e)};t.Cleanup(func(){db.Close()});return New(db,slog.New(slog.NewTextHandler(io.Discard,nil)),"admin-test-token") }
func call(t *testing.T,h http.Handler,method,path,token string,body any)(int,map[string]any){t.Helper();var raw []byte;if body!=nil{raw,_=json.Marshal(body)};r:=httptest.NewRequest(method,path,bytes.NewReader(raw));if token!=""{r.Header.Set("Authorization","Bearer "+token)};w:=httptest.NewRecorder();h.ServeHTTP(w,r);var out map[string]any;_=json.Unmarshal(w.Body.Bytes(),&out);return w.Code,out}

func registerUser(t *testing.T, h http.Handler, email, displayName string) string {
	t.Helper()
	status, result := call(t, h, "POST", "/api/v1/auth/register", "", map[string]any{"email": email, "displayName": displayName, "password": "correct horse battery"})
	if status != 201 { t.Fatalf("register %s status=%d body=%v", email, status, result) }
	return result["accessToken"].(string)
}

func TestCreateAndJoinRoom(t *testing.T){h:=testAPI(t);hostAccount:=registerUser(t,h,"host@example.test","Host");guestAccount:=registerUser(t,h,"guest@example.test","Guest");status,created:=call(t,h,"POST","/api/v1/rooms",hostAccount,map[string]any{"name":"Friday LAN","username":"Host","maxPlayers":4});if status!=201{t.Fatalf("create status=%d body=%v",status,created)};invite:=created["inviteCode"].(string);roomID:=created["roomId"].(string);status,joined:=call(t,h,"POST","/api/v1/rooms/join",guestAccount,map[string]any{"inviteCode":invite,"username":"Guest"});if status!=200||joined["status"]!="approved"{t.Fatalf("join status=%d body=%v",status,joined)};token:=created["accessToken"].(string);status,loaded:=call(t,h,"GET","/api/v1/rooms/"+roomID,token,nil);if status!=200{t.Fatalf("get room status=%d body=%v",status,loaded)};members:=loaded["members"].([]any);if len(members)!=2{t.Fatalf("members=%d",len(members))} }

func TestRoomPassword(t *testing.T){h:=testAPI(t);hostAccount:=registerUser(t,h,"host@example.test","Host");guestAccount:=registerUser(t,h,"guest@example.test","Guest");_,created:=call(t,h,"POST","/api/v1/rooms",hostAccount,map[string]any{"name":"Password Room","username":"Host","password":"correct horse"});invite:=created["inviteCode"].(string);status,_:=call(t,h,"POST","/api/v1/rooms/join",guestAccount,map[string]any{"inviteCode":invite,"username":"Guest","password":"wrong"});if status!=401{t.Fatalf("wrong password status=%d",status)};status,joined:=call(t,h,"POST","/api/v1/rooms/join",guestAccount,map[string]any{"inviteCode":invite,"username":"Guest","password":"correct horse"});if status!=200||joined["status"]!="approved"{t.Fatalf("valid password status=%d body=%v",status,joined)} }

func TestApprovalAndCapacity(t *testing.T){h:=testAPI(t);hostAccount:=registerUser(t,h,"host@example.test","Host");guestAccount:=registerUser(t,h,"guest@example.test","Guest");thirdAccount:=registerUser(t,h,"third@example.test","Third");_,created:=call(t,h,"POST","/api/v1/rooms",hostAccount,map[string]any{"name":"Closed Queue","username":"Host","maxPlayers":2,"requireApproval":true});invite:=created["inviteCode"].(string);host:=created["accessToken"].(string);roomID:=created["roomId"].(string);_,joined:=call(t,h,"POST","/api/v1/rooms/join",guestAccount,map[string]any{"inviteCode":invite,"username":"Guest"});if joined["status"]!="pending"{t.Fatalf("expected pending: %v",joined)};guestToken:=joined["accessToken"].(string);uid:=joined["userId"].(string);status,_:=call(t,h,"POST","/api/v1/rooms/"+roomID+"/approve",host,map[string]string{"userId":uid});if status!=200{t.Fatalf("approve status=%d",status)};status,membership:=call(t,h,"GET","/api/v1/rooms/"+roomID+"/membership",guestToken,nil);if status!=200||membership["status"]!="approved"||membership["networkSecret"]==nil{t.Fatalf("membership status=%d body=%v",status,membership)};status,full:=call(t,h,"POST","/api/v1/rooms/join",thirdAccount,map[string]any{"inviteCode":invite,"username":"Third"});if status!=409||full["error"].(map[string]any)["code"]!="room_full"{t.Fatalf("capacity status=%d body=%v",status,full)} }

func TestInviteRotationAndAuthorization(t *testing.T){h:=testAPI(t);hostAccount:=registerUser(t,h,"host@example.test","Host");guestAccount:=registerUser(t,h,"guest@example.test","Guest");_,created:=call(t,h,"POST","/api/v1/rooms",hostAccount,map[string]any{"name":"Private","username":"Host"});id:=created["roomId"].(string);host:=created["accessToken"].(string);old:=created["inviteCode"].(string); denied,_:=call(t,h,"POST","/api/v1/rooms","",map[string]any{"name":"No Account","username":"Host"});if denied!=401{t.Fatalf("room create without account status=%d",denied)};status,rotated:=call(t,h,"POST","/api/v1/rooms/"+id+"/invite/rotate",host,nil);if status!=200||rotated["inviteCode"]==old{t.Fatalf("rotation status=%d body=%v",status,rotated)};status,_=call(t,h,"POST","/api/v1/rooms/join",guestAccount,map[string]any{"inviteCode":old,"username":"Guest"});if status!=404{t.Fatalf("old invite should fail, got %d",status)};status,_=call(t,h,"DELETE","/api/v1/rooms/"+id,"bad-token",nil);if status!=401{t.Fatalf("unauthorized delete got %d",status)} }

func TestAccountRegistrationAndSession(t *testing.T){h:=testAPI(t);status,registered:=call(t,h,"POST","/api/v1/auth/register","",map[string]any{"email":"player@example.test","displayName":"بازیکن اول","password":"correct horse battery"});if status!=201{t.Fatalf("register status=%d body=%v",status,registered)};token:=registered["accessToken"].(string);status,profile:=call(t,h,"GET","/api/v1/auth/me",token,nil);if status!=200||profile["user"].(map[string]any)["displayName"]!="بازیکن اول"{t.Fatalf("profile status=%d body=%v",status,profile)};status,_=call(t,h,"POST","/api/v1/auth/register","",map[string]any{"email":"player@example.test","displayName":"Other","password":"correct horse battery"});if status!=409{t.Fatalf("duplicate registration status=%d",status)};status,_=call(t,h,"POST","/api/v1/auth/login","",map[string]any{"email":"player@example.test","password":"incorrect password"});if status!=401{t.Fatalf("wrong password status=%d",status)};status,logged:=call(t,h,"POST","/api/v1/auth/login","",map[string]any{"email":"PLAYER@example.test","password":"correct horse battery"});if status!=200{t.Fatalf("login status=%d body=%v",status,logged)};status,_=call(t,h,"PATCH","/api/v1/auth/me",token,map[string]string{"displayName":"بازیکن تازه"});if status!=200{t.Fatalf("profile update status=%d",status)};status,_=call(t,h,"POST","/api/v1/auth/logout",token,nil);if status!=200{t.Fatalf("logout status=%d",status)};status,_=call(t,h,"GET","/api/v1/auth/me",token,nil);if status!=401{t.Fatalf("revoked session status=%d",status)} }
